sp_widget.css:
.todo-summary-cell {
	position: relative;
  margin-bottom: 0;
  border: none;
  box-shadow:none;
  border-bottom: 1px solid $border;
	.todo-summary-body {
		padding-top: 10px;
		padding-bottom: 10px;
		display: flex;
    align-items:center;
    min-height:82px;
		.todo-summary-details {
			overflow: hidden;
			text-align: left !important;
      margin-right: 15px;
      .task-title {
        font-size: 1.5rem;
        text-overflow: ellipsis;
        overflow: hidden;
        white-space: nowrap;
			}
      .case-title {
        font-size: 1.4rem;
        text-overflow: ellipsis;
        color:$color-darkest;
        overflow: hidden;
        white-space: nowrap;
      }
      .text-muted {
        font-size: 1.4rem;
      }
      .todo-status {
      	padding-top:10px;
      }
      .fa-check-circle {
				padding-right: 1px;
        padding-left: 1px;
			}
		}
    .todo-summary-icon {
      display: flex;
    	vertical-align: middle;
    	padding: 0 0 0 15px;
    	font-size: 1.82rem;
      justify-content: center;
      .fa-level-up {
        color: $color-light;
        transform: rotate(90deg);
        vertical-align: -webkit-baseline-middle;
        margin-right: 15px;
    	} 
    }
  }
}


/*Increasing width for childern tasks*/
.todo-summary-body{
  .indent-xsm {
    padding-left: 48px !important;
  }

  .indent-xs {
    padding-left: 0px;
  }
}


/* IE Fixes */
@media screen and (-ms-high-contrast: active), (-ms-high-contrast: none) {  
  .todo-summary-body {
    .indent-xs {
      width: 5em;
    }	
  }
}

sp_widget.script:
(function() {
	var fields = ['sysId', 'tableName', 'displayValueList', 'dueDateDisplayValue', 'level', 'onTicketPage', 'isCompleted', 'hasDueDate'];
	function copyFields(from) {
		var field;
		for (var x in fields) {
			field = fields[x];
			if (!gs.nil(from[field])) {
				data[field] = from[field];
			}
		}
	}
	if (input) {
		copyFields(input);
	}
	if (options) {
		copyFields(options);
	}
})();
